css:
.justlead-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b3440;
    background: linear-gradient(180deg, #eef1f4 0%, #e3e8ee 100%);
    border-radius: 16px;
}

.justlead-container * {
    box-sizing: border-box;
}

.justlead-header {
    position: relative;
    text-align: center;
    padding: 28px 22px 24px;
    background:
        repeating-linear-gradient(135deg, rgba(255,255,255,0.04) 0px, rgba(255,255,255,0.04) 2px, transparent 2px, transparent 9px),
        linear-gradient(135deg, #1f2a37 0%, #2c3e50 60%, #34515e 100%);
    color: #f3f6f9;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #1a232e;
    border-top: 5px solid #d98324;
    box-shadow: 0 10px 28px rgba(31, 42, 55, 0.30);
}

.justlead-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.justlead-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f0b46a;
    background: rgba(217, 131, 36, 0.14);
    border: 1px solid rgba(217, 131, 36, 0.38);
    padding: 5px 14px;
    border-radius: 4px;
}

.justlead-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c9d4de;
}

.justlead-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4d5b6a;
    margin-bottom: 18px;
    padding: 4px 2px;
}

.justlead-period-counter #currentDay,
.justlead-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f6f78;
}

.justlead-round-name {
    background: #1f6f78;
    color: #eafafb;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.justlead-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a4b13;
    background: #f6e0c2;
    border: 1px solid #e3b985;
    padding: 4px 12px;
    border-radius: 4px;
}

.justlead-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.justlead-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #d4dce4;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.08);
    border-left: 5px solid #8595a4;
}

.justlead-card-trust { border-left-color: #1f6f78; }
.justlead-card-fair { border-left-color: #3a6ea5; }
.justlead-card-prod { border-left-color: #2e8b57; }
.justlead-card-comp { border-left-color: #d98324; }

.justlead-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7a89;
}

.justlead-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 4px;
    color: #1f2a37;
    font-variant-numeric: tabular-nums;
}

.justlead-card-trust .justlead-value { color: #1f6f78; }
.justlead-card-fair .justlead-value { color: #3a6ea5; }
.justlead-card-prod .justlead-value { color: #2e8b57; }
.justlead-card-comp .justlead-value { color: #d98324; }

.justlead-sublabel {
    font-size: 0.75rem;
    color: #7b8794;
    line-height: 1.35;
}

.justlead-trust-danger { border-left-color: #c0392b; }
.justlead-trust-danger .justlead-value { color: #c0392b; }
.justlead-trust-strong { border-left-color: #1f6f78; }
.justlead-trust-strong .justlead-value { color: #15813f; }

.justlead-prod-low .justlead-value { color: #c0392b; }
.justlead-comp-low { border-left-color: #c0392b; }
.justlead-comp-low .justlead-value { color: #c0392b; }

.justlead-status-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    background: #ffffff;
    border: 1px solid #d4dce4;
    border-radius: 10px;
    padding: 12px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.06);
}

.justlead-bar-item {
    display: flex;
    flex-direction: column;
    flex: 1 1 200px;
}

.justlead-bar-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #6b7a89;
}

.justlead-status-bar #targetDisplay,
.justlead-status-bar #cncDisplay,
.justlead-status-bar #grievanceDisplay {
    font-size: 1.02rem;
    font-weight: 800;
    color: #1f2a37;
    letter-spacing: 0.2px;
}

.justlead-grievance-resolved #grievanceDisplay { color: #15813f; }
.justlead-grievance-arbitration #grievanceDisplay { color: #c0392b; }
.justlead-grievance-conceded #grievanceDisplay { color: #d98324; }

.justlead-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #d98324;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.08);
}

.justlead-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.justlead-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f2a37;
    margin-bottom: 6px;
}

.justlead-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #41505f;
}

.justlead-briefing-text strong { color: #1f6f78; }
.justlead-briefing-text em { color: #8a4b13; font-style: italic; }

.justlead-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d4dce4;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.08);
}

.justlead-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f2a37;
    border-bottom: 2px solid #e3e8ee;
    padding-bottom: 8px;
}

.justlead-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3440;
    margin: 16px 0 6px;
}

.justlead-container select,
.justlead-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b9c4ce;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #f7f9fb;
    color: #1f2a37;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.justlead-container select:focus,
.justlead-container input[type="number"]:focus {
    outline: none;
    border-color: #1f6f78;
    box-shadow: 0 0 0 3px rgba(31, 111, 120, 0.18);
}

.justlead-container select option {
    background-color: #ffffff;
    color: #1f2a37;
}

.justlead-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f6f78;
}

.justlead-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4d5b6a;
    margin-top: 4px;
}

.justlead-range-readout span:nth-child(2) {
    color: #1f6f78;
    font-weight: 800;
}

.justlead-hint {
    font-size: 0.8rem;
    color: #7b8794;
    margin-top: 4px;
    line-height: 1.4;
}

.justlead-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.justlead-container .btn-primary {
    background: linear-gradient(135deg, #155a61 0%, #1f6f78 100%);
    border: none;
    color: #f3fbfc;
    padding: 11px 26px;
    border-radius: 7px;
    box-shadow: 0 6px 16px rgba(31, 111, 120, 0.35);
}

.justlead-container .btn-primary:hover {
    filter: brightness(1.08);
}

.justlead-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #b9c4ce;
    color: #4d5b6a;
    background: transparent;
}

.justlead-coach {
    background: linear-gradient(160deg, #20323f 0%, #2c3e50 100%);
    color: #dfe8ef;
    border: 1px solid #1a232e;
    border-left: 5px solid #d98324;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 42, 55, 0.20);
}

.justlead-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0b46a;
    margin-bottom: 8px;
}

.justlead-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.justlead-coach-body strong { color: #6fc7cf; }
.justlead-coach-body em { color: #f0b46a; font-style: italic; }

.justlead-history,
.justlead-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d4dce4;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.08);
}

.justlead-history h3,
.justlead-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f2a37;
}

.justlead-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #41505f;
}

.justlead-container table#usfHistoryTable th {
    background: #f0f3f6;
    color: #1f6f78;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dce4;
}

.justlead-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e3e8ee;
    color: #41505f;
}

.justlead-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fb;
}

.justlead-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .justlead-container {
        padding: 14px;
    }
    .justlead-header h1 {
        font-size: 1.7rem;
    }
    .justlead-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .justlead-value {
        font-size: 2rem;
    }
    .justlead-clock {
        margin-left: 0;
    }
    .justlead-period-counter {
        font-size: 0.88rem;
    }
    .justlead-status-bar {
        flex-direction: column;
        gap: 8px;
    }
    .justlead-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0: completion debrief card (append-only, self-contained) ── */
.jl-cm { font-family: inherit; color: #1f2a37; padding: 4px 2px 2px; }
.jl-cm-scoreblock { text-align: center; padding: 14px 12px 16px; background: linear-gradient(160deg,#f7f9fb,#e3e8ee); border-radius: 14px; border: 1px solid #d4dce4; }
.jl-cm-scorenum { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #1f6f78; }
.jl-cm-scoremax { font-size: 1.15rem; font-weight: 600; color: #7b8794; margin-left: 2px; }
.jl-cm-scorelabel { font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: #7b8794; margin-top: 6px; }
.jl-cm-grade { font-size: 1.16rem; font-weight: 700; color: #1f2a37; margin-top: 8px; }
.jl-cm-badge { display: inline-block; margin-top: 10px; padding: 4px 14px; border-radius: 999px; font-size: .78rem; font-weight: 700; }
.jl-cm-badge-pass { background: #d3ece2; color: #256b48; }
.jl-cm-badge-miss { background: #f6d9d4; color: #a5341f; }
.jl-cm-kpis { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin: 16px 0 4px; }
.jl-cm-kpi { background: #ffffff; border: 1px solid #e3e8ee; border-left: 3px solid #1f6f78; border-radius: 10px; padding: 12px 8px; text-align: center; }
.jl-cm-k-trust { border-left-color: #1f6f78; }
.jl-cm-k-fair { border-left-color: #3a6ea5; }
.jl-cm-k-prod { border-left-color: #2e8b57; }
.jl-cm-k-comp { border-left-color: #d98324; }
.jl-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1f2a37; line-height: 1.05; }
.jl-cm-k-trust .jl-cm-kpi-val { color: #1f6f78; }
.jl-cm-k-fair .jl-cm-kpi-val { color: #3a6ea5; }
.jl-cm-k-prod .jl-cm-kpi-val { color: #2e8b57; }
.jl-cm-k-comp .jl-cm-kpi-val { color: #d98324; }
.jl-cm-kpi-label { font-size: .74rem; font-weight: 700; color: #41505f; margin-top: 5px; }
.jl-cm-kpi-sub { font-size: .64rem; color: #8a97a4; margin-top: 2px; line-height: 1.25; }
.jl-cm-insights { margin: 16px 2px 6px; }
.jl-cm-insights h6 { font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; color: #7b8794; margin: 0 0 8px; font-weight: 700; }
.jl-cm-insights ul { margin: 0; padding-left: 18px; }
.jl-cm-insights li { font-size: .86rem; line-height: 1.5; color: #2b3a47; margin-bottom: 7px; }
.jl-cm-footer { margin-top: 14px; padding-top: 10px; border-top: 1px solid #e3e8ee; font-size: .72rem; color: #8a97a4; text-align: center; font-style: italic; }
@media (max-width: 640px) { .jl-cm-kpis { grid-template-columns: repeat(2,1fr); } .jl-cm-scorenum { font-size: 2.6rem; } }

