(function() {
    'use strict';

    class JustLeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Just Leader`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Cascadia Precision Components Ltd.).
            this.TARGET = 4.2;          // CAD 4.2M labour cost to remove (fixed mandate)
            this.POSITIONS = 38;        // positions cut (16% of headcount)
            this.SURVIVORS = 202;       // people who stay
            this.CNC_TOTAL = 6;         // scarce CNC programmers at flight risk
            this.TRUST_START = 78;      // pre-crisis pulse-survey trust score
            this.TRUST_DANGER = 55;     // below ~55 precedes retained-talent quit spikes
            this.SHORTFALL = 1.8;       // CAD 1.8M still short if headcount is conceded

            // Concept truths (the defensible play).
            this.TRUE_FRAME = `process`;
            this.TRUE_DEFECT = `opaque`;
            this.TRUE_RAIL = `skills`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: this.TRUST_START,    // pulse-survey trust score (0–100)
                    fairness: 50,               // composite of the four justice dimensions (0–100)
                    productivity: 100,          // survivor productivity, % of baseline
                    composure: 60,              // leader self-regulation (0–100)
                    costRemoved: 0,             // CAD M of labour cost actually removed
                    cncRetained: this.CNC_TOTAL,
                    grievanceState: `open`,     // open | mediated | arbitration | conceded
                    concededHeadcount: false,
                    truthLeaked: false,
                    survivorsIgnored: false,
                    trustHistory: [this.TRUST_START],
                    fairnessHistory: [50],
                    productivityHistory: [100],
                    composureHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the CLASSIC ERRORS — a blind click-through
                // must measurably underperform (number-first, vague truth, leavers-only,
                // no fair-process spend, defensive reaction, conceded grievance, ignored survivors).
                state.decisions = {
                    frame: `number`,
                    defect: `cost`,
                    focus: 40,
                    criteria: `seniority`,
                    truth: `vague`,
                    audience: `leavers`,
                    invest: 0,
                    reset: `defend`,
                    dignity: `brief`,
                    grievance: `concede`,
                    survivor: `silent`,
                    cnc: `nothing`,
                    follow: `none`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const df = document.getElementById(`defectInput`);
                const fo = document.getElementById(`focusInput`);
                if (fr) decisions.frame = fr.value;
                if (df) decisions.defect = df.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const cr = document.getElementById(`criteriaInput`);
                const tr = document.getElementById(`truthInput`);
                const au = document.getElementById(`audienceInput`);
                const iv = document.getElementById(`investInput`);
                if (cr) decisions.criteria = cr.value;
                if (tr) decisions.truth = tr.value;
                if (au) decisions.audience = au.value;
                if (iv) decisions.invest = parseFloat(iv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_value`); return false;
                }
            } else if (round === 3) {
                const rs = document.getElementById(`resetInput`);
                const dg = document.getElementById(`dignityInput`);
                const gr = document.getElementById(`grievanceInput`);
                if (rs) decisions.reset = rs.value;
                if (dg) decisions.dignity = dg.value;
                if (gr) decisions.grievance = gr.value;
                if (!decisions.reset || !decisions.dignity || !decisions.grievance) {
                    warn(`warn_r3_missing`); return false;
                }
            } else if (round === 4) {
                const sv = document.getElementById(`survivorInput`);
                const cn = document.getElementById(`cncInput`);
                const fl = document.getElementById(`followInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sv) decisions.survivor = sv.value;
                if (cn) decisions.cnc = cn.value;
                if (fl) decisions.follow = fl.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let trustDelta = 0, fairDelta = 0, prodDelta = 0, compDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the justice landscape (Common Error 1: number-first, process as paperwork).
                switch (d.frame) {
                    case `process`: fairDelta += 12; trustDelta += 3; compDelta += 4; coachKey = `coach_r1_process`; break;
                    case `number`: fairDelta -= 8; trustDelta -= 3; coachKey = `coach_r1_number`; break;
                    case `speed`: fairDelta -= 5; trustDelta -= 2; coachKey = `coach_r1_speed`; break;
                    case `legal`: fairDelta -= 2; coachKey = `coach_r1_legal`; break;
                }

                // Spot the real defect in the draft criteria (distributive + procedural).
                switch (d.defect) {
                    case `opaque`: fairDelta += 8; if (d.frame === `process`) coachKey = `coach_r1_sharp`; break;
                    case `cost`: fairDelta -= 4; break;
                    case `union`: fairDelta -= 3; break;
                    case `none`: fairDelta -= 8; trustDelta -= 2; coachKey = `coach_r1_none`; break;
                }

                // How much attention on process & the four justice dimensions vs the math.
                if (d.focus >= 60) { fairDelta += 6; compDelta += 3; }
                else if (d.focus <= 25) { fairDelta -= 6; coachKey = `coach_r1_lowfocus`; }

                summaryKey = (d.frame === `process` && d.defect === `opaque`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design criteria + communication architecture (Common Errors 2 & 5).
                // Selection criteria — defensible procedural justice vs cheap/expedient.
                switch (d.criteria) {
                    case `skills`: fairDelta += 14; trustDelta += 4; ds.costRemoved += this.TARGET; break;
                    case `seniority`: fairDelta -= 8; trustDelta -= 4; ds.costRemoved += this.TARGET; coachKey = `coach_r2_seniority`; break;
                    case `costfirst`: fairDelta -= 12; trustDelta -= 6; ds.costRemoved += this.TARGET; coachKey = `coach_r2_costfirst`; break;
                }

                // Informational justice — disclose the painful commercial truth, or it leaks.
                switch (d.truth) {
                    case `full`: fairDelta += 10; trustDelta += 6; break;
                    case `partial`: fairDelta -= 2; trustDelta -= 2; break;
                    case `vague`: fairDelta -= 8; trustDelta -= 8; ds.truthLeaked = true; coachKey = `coach_r2_vague`; break;
                }

                // Audience — leavers AND the 202 survivors, not leavers alone (Common Error 5).
                switch (d.audience) {
                    case `both`: fairDelta += 6; trustDelta += 4; break;
                    case `leavers`: trustDelta -= 4; prodDelta -= 3; ds.survivorsIgnored = true; if (coachKey === `coach_default`) coachKey = `coach_r2_leavers`; break;
                    case `board`: trustDelta -= 3; fairDelta -= 3; break;
                }

                // Spend on the fair process — appeal panel, redeployment, retraining.
                ds.costRemoved -= d.invest;     // every dollar of fairness is a dollar off the net target
                if (d.invest >= 0.6) { fairDelta += 8; trustDelta += 4; compDelta += 2; }
                else if (d.invest >= 0.3) { fairDelta += 4; trustDelta += 2; }
                else { fairDelta -= 4; if (d.criteria === `skills`) coachKey = `coach_r2_underfunded`; }

                summaryKey = (d.criteria === `skills` && d.truth === `full` && d.audience === `both`) ? `sum_r2_good` :
                             (d.truth === `vague` ? `sum_r2_leaked` : `sum_r2_weak`);
            } else if (round === 3) {
                // The live conversation + the grievance (Common Errors 3 & 4).
                // Mindfulness self-regulation reset — the fairness tool, not a perk.
                switch (d.reset) {
                    case `reset`: compDelta += 16; fairDelta += 8; trustDelta += 3; break;
                    case `defend`: compDelta -= 12; fairDelta -= 10; trustDelta -= 4; coachKey = `coach_r3_defend`; break;
                    case `placate`: compDelta -= 4; fairDelta -= 6; trustDelta -= 3; coachKey = `coach_r3_placate`; break;
                }

                // Interpersonal justice — dignity in the dismissal conversation.
                switch (d.dignity) {
                    case `dignity`: fairDelta += 10; trustDelta += 4; break;
                    case `brief`: fairDelta -= 5; trustDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_brief`; break;
                    case `blame`: fairDelta -= 9; trustDelta -= 5; coachKey = `coach_r3_blame`; break;
                }

                // Grievance handling — hold the headcount with genuine procedural voice.
                switch (d.grievance) {
                    case `mediate`:
                        fairDelta += 8; trustDelta += 5; ds.grievanceState = `mediated`;
                        if (d.reset === `reset` && d.dignity === `dignity`) coachKey = `coach_r3_held`;
                        break;
                    case `arbitrate`:
                        fairDelta -= 6; trustDelta -= 4; ds.grievanceState = `arbitration`;
                        coachKey = `coach_r3_arbitrate`;
                        break;
                    case `concede`:
                        // Trade one hard fair call for repeated unfair ones; still CAD 1.8M short.
                        trustDelta -= 6; fairDelta -= 4; ds.grievanceState = `conceded`;
                        ds.concededHeadcount = true; ds.costRemoved -= this.SHORTFALL;
                        coachKey = `coach_r3_concede`;
                        break;
                }

                summaryKey = (d.reset === `reset` && d.dignity === `dignity` && d.grievance === `mediate`) ? `sum_r3_good` :
                             (d.reset === `defend` ? `sum_r3_reactive` :
                             (d.grievance === `concede` ? `sum_r3_caved` : `sum_r3_weak`));
            } else if (round === 4) {
                // Recover trust & stabilise the survivors (Common Error 5 — the real audience).
                switch (d.survivor) {
                    case `honest`: trustDelta += 12; fairDelta += 6; prodDelta += 8; break;
                    case `reassure`: trustDelta += 2; prodDelta += 1; coachKey = `coach_r4_reassure`; break;
                    case `silent`: trustDelta -= 6; prodDelta -= 6; ds.survivorsIgnored = true; coachKey = `coach_r4_silent`; break;
                }

                // Retain the six scarce CNC programmers — they read the leavers' treatment as a signal.
                switch (d.cnc) {
                    case `signal`:
                        trustDelta += 4;
                        // Retention holds if fairness was real; cash alone is read as a bribe.
                        if (ds.fairness + fairDelta >= 55 && !ds.concededHeadcount) ds.cncRetained = this.CNC_TOTAL;
                        else ds.cncRetained = Math.max(this.CNC_TOTAL - 1, Math.round(this.CNC_TOTAL * 0.7));
                        break;
                    case `money`:
                        ds.cncRetained = (ds.fairness + fairDelta >= 60) ? this.CNC_TOTAL - 1 : this.CNC_TOTAL - 2;
                        coachKey = `coach_r4_money`;
                        break;
                    case `nothing`:
                        ds.cncRetained = (ds.fairness + fairDelta >= 65) ? this.CNC_TOTAL - 1 : this.CNC_TOTAL - 3;
                        coachKey = `coach_r4_nothing`;
                        break;
                }
                ds.cncRetained = Math.max(0, Math.min(this.CNC_TOTAL, ds.cncRetained));

                // Visible follow-through proves fairness was real, not theatre.
                switch (d.follow) {
                    case `real`: fairDelta += 10; trustDelta += 6; break;
                    case `optics`: trustDelta -= 4; fairDelta -= 4; coachKey = `coach_r4_optics`; break;
                    case `none`: trustDelta -= 5; fairDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r4_none`; break;
                }

                if (d.conviction >= 60) { fairDelta += 4; compDelta += 3; }
                else if (d.conviction <= 25) { fairDelta -= 4; trustDelta -= 2; }

                if (d.survivor === `honest` && d.follow === `real` && d.cnc === `signal`) coachKey = `coach_r4_recovered`;

                summaryKey = (d.survivor === `honest` && d.follow === `real`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Cap the cost removed at the CAD 4.2M target (fairness spend is the only thing
            // that reduces the net; conceding the headcount opens the CAD 1.8M shortfall).
            ds.costRemoved = Math.round(ds.costRemoved * 10) / 10;

            // Survivor productivity tracks perceived fairness: a fair process holds the loss
            // under 5%; an unfair one drives an 8–15% drop (Numbers Reference Card).
            const projectedFair = Math.max(0, Math.min(100, ds.fairness + fairDelta));
            if (projectedFair >= 70) prodDelta += 3;
            else if (projectedFair < 45) prodDelta -= 5;
            if (ds.truthLeaked) prodDelta -= 2;

            // Apply deltas, clamped.
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustDelta)));
            ds.fairness = Math.max(0, Math.min(100, Math.round(ds.fairness + fairDelta)));
            ds.productivity = Math.max(60, Math.min(105, Math.round(ds.productivity + prodDelta)));
            ds.composure = Math.max(0, Math.min(100, Math.round(ds.composure + compDelta)));

            ds.trustHistory.push(ds.trust);
            ds.fairnessHistory.push(ds.fairness);
            ds.productivityHistory.push(ds.productivity);
            ds.composureHistory.push(ds.composure);
            // ── v1.1.0 fix: persist the composite where Express reporting reads it ──
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            const composite = this._composite(ds);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;


            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                trust: ds.trust,
                trustDelta: Math.round(trustDelta),
                fairness: ds.fairness,
                fairnessDelta: Math.round(fairDelta),
                productivity: ds.productivity,
                productivityDelta: Math.round(prodDelta),
                composure: ds.composure,
                composureDelta: Math.round(compDelta),
                costRemoved: ds.costRemoved,
                cncRetained: ds.cncRetained,
                grievanceState: ds.grievanceState,
                concededHeadcount: ds.concededHeadcount,
                truthLeaked: ds.truthLeaked,
                score: composite,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Canadian dollars. English "C$4.2M"; Spanish "4,2 M C$" (comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M C$`;
            }
            return `${sign}C$${abs.toFixed(1)}M`;
        }

