            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            switch (stateCode) {
                case `mediated`: return t(`grievance_mediated`);
                case `arbitration`: return t(`grievance_arbitration`);
                case `conceded`: return t(`grievance_conceded`);
                default: return t(`grievance_open`);
