        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = Math.round(ds.trust);
            const fairness = Math.round(ds.fairness);
            const productivity = Math.round(ds.productivity);
            const composure = Math.round(ds.composure);

            // Composite weights the survivor-trust outcome heaviest (the real long-run scoreboard).
            const composite = Math.round(
                trust * 0.34 + fairness * 0.28 + productivity * 0.22 + composure * 0.16
            );

            const trustHeld = trust >= this.TRUST_DANGER;
            const fairProcess = fairness >= 60;
            const survivorsHeld = productivity >= 95;
            const regulated = composure >= 55;
            const cncKept = ds.cncRetained >= this.CNC_TOTAL;
            const targetMet = ds.costRemoved >= this.TARGET - 0.65 && !ds.concededHeadcount;

            let performance = window.mySimulation.t(`grade_fractured`);
            if (trustHeld && fairProcess && survivorsHeld && composite >= 75 && targetMet) performance = window.mySimulation.t(`grade_just`);
            else if (fairProcess && trustHeld && cncKept) performance = window.mySimulation.t(`grade_fair`);
            else if (ds.concededHeadcount) performance = window.mySimulation.t(`grade_caved`);
            else if (!trustHeld && trust < 50) performance = window.mySimulation.t(`grade_collapsed`);
            else if (composite >= 55) performance = window.mySimulation.t(`grade_mixed`);

            const insights = [];
            if (trustHeld && fairProcess && survivorsHeld) insights.push(window.mySimulation.t(`insight_just`));
            else if (ds.concededHeadcount) insights.push(window.mySimulation.t(`insight_caved`));
            else if (!trustHeld) insights.push(window.mySimulation.t(`insight_trustfell`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.truthLeaked) insights.push(window.mySimulation.t(`insight_leaked`));
            if (composure < 40) insights.push(window.mySimulation.t(`insight_reactive`));
            if (ds.survivorsIgnored) insights.push(window.mySimulation.t(`insight_survivors`));
            if (!cncKept) insights.push(window.mySimulation.t(`insight_cnc`));
            else if (trustHeld && fairProcess) insights.push(window.mySimulation.t(`insight_cnckept`));

            return {
                trust: trust,
                fairness: fairness,
                productivity: productivity,
                composure: composure,
                cncRetained: ds.cncRetained,
                trustHeld: trustHeld,
                fairProcess: fairProcess,
                survivorsHeld: survivorsHeld,
                regulated: regulated,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── v1.1.0 fix: persist composite score + localized completion debrief ──
        _composite(ds) {
            // Verbatim mirror of getPerformanceSummary()'s composite (no scoring change).
            const trust = Math.round(ds.trust || 0);
            const fairness = Math.round(ds.fairness || 0);
            const productivity = Math.round(ds.productivity || 0);
            const composure = Math.round(ds.composure || 0);
            return Math.round(trust * 0.34 + fairness * 0.28 + productivity * 0.22 + composure * 0.16);
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const composite = (typeof s.composite === `number`) ? s.composite : 0;
            const grade = s.performance || ``;
            const held = !!(s.trustHeld && s.fairProcess);
            const trust = (s.trust != null) ? s.trust : 0;
            const fairness = (s.fairness != null) ? s.fairness : 0;
            const productivity = (s.productivity != null) ? s.productivity : 0;
            const composure = (s.composure != null) ? s.composure : 0;
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const badgeClass = held ? `jl-cm-badge-pass` : `jl-cm-badge-miss`;
            const badgeText = held ? t(`cm_badge_beat`) : t(`cm_badge_missed`);

            const kpi = (label, val, sub, cls) => `
                <div class="jl-cm-kpi ${cls}">
                    <div class="jl-cm-kpi-val">${val}</div>
                    <div class="jl-cm-kpi-label">${label}</div>
                    <div class="jl-cm-kpi-sub">${sub}</div>
                </div>`;

            let insightHtml = ``;
            insights.forEach((it) => { insightHtml += `<li>${it}</li>`; });

            return `
                <div class="jl-cm">
                    <div class="jl-cm-scoreblock">
                        <div class="jl-cm-scorenum">${composite}<span class="jl-cm-scoremax">/100</span></div>
                        <div class="jl-cm-scorelabel">${t(`cm_score_label`)}</div>
                        <div class="jl-cm-grade">${grade}</div>
                        <span class="jl-cm-badge ${badgeClass}">${badgeText}</span>
                    </div>
                    <div class="jl-cm-kpis">
                        ${kpi(t(`trust_label`), trust, t(`trust_sub`), `jl-cm-k-trust`)}
                        ${kpi(t(`fair_label`), fairness, t(`fair_sub`), `jl-cm-k-fair`)}
                        ${kpi(t(`prod_label`), productivity + `%`, t(`prod_sub`), `jl-cm-k-prod`)}
                        ${kpi(t(`comp_label`), composure, t(`comp_sub`), `jl-cm-k-comp`)}
                    </div>
                    ${insightHtml ? `<div class="jl-cm-insights"><h6>${t(`cm_insights_title`)}</h6><ul>${insightHtml}</ul></div>` : ``}
                    <div class="jl-cm-footer">${t(`cm_footer`)}</div>
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.concededHeadcount) return window.mySimulation.t(`hint_caved`);
            if (ds.truthLeaked) return window.mySimulation.t(`hint_leaked`);
            if (ds.composure < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_composure`);
            if (ds.trust < this.TRUST_DANGER) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.survivorsIgnored) return window.mySimulation.t(`hint_survivors`);
            if (ds.trust >= 70 && ds.fairness >= 65 && ds.productivity >= 95) return window.mySimulation.t(`hint_strong`);
            return null;
        }

